package com.gameaggregator.contractservice.domain;import jakarta.persistence.*;import java.util.UUID;@Entity @Table(name="contract_parties") public class ContractParty{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID contractId;@Column(nullable=false)public UUID partyId;@Column(nullable=false)public String partyType;@Column(nullable=false)public String role;protected ContractParty(){}public ContractParty(UUID c,UUID p,String t,String r){contractId=c;partyId=p;partyType=t;role=r;}}